// TraceNaut brand marks. `node scripts/icons/brand.mjs explore <dir>` renders candidate
// directions for review; the chosen mark is generated by `markSvg()` (used by build-icons).
import { mkdirSync, writeFileSync } from 'node:fs';
import { P, Icon, line, shade, tint } from './iso.mjs';

export const BRAND = { indigo: '#5b5bd6', deep: '#3730a3', light: '#a5b4fc', cyan: '#22d3ee', ink: '#14162b' };

const make = (name, draw) => {
  const i = new Icon(name);
  draw(i);
  return i.render();
};

const plate = (i, z, hue, opts) => i.box(-7.5, -7.5, z, 15, 15, 1.8, hue, opts);

export const CANDIDATES = {
  // A · Strata trace: layers, and one path followed down through them.
  'a-strata': () =>
    make('a', (i) => {
      plate(i, 0, tint(BRAND.indigo, 0.35));
      plate(i, 4.6, tint(BRAND.indigo, 0.15), { noShadow: true });
      const top = plate(i, 9.2, BRAND.indigo, { noShadow: true });
      void top;
      const [x0, y0] = P(0, 0, 11);
      const [x1, y1] = P(0, 0, 1.8);
      i.raw(line(`M${x0} ${y0}L${x1} ${y1}`, BRAND.cyan, 1.6) + `<circle cx="${x0}" cy="${y0}" r="1.6" fill="#fff" stroke="${BRAND.cyan}" stroke-width="1.1"/><circle cx="${x1}" cy="${y1}" r="1.9" fill="${BRAND.cyan}"/>`);
    }),
  // B · Cutaway: a solid with one corner removed, revealing what is inside.
  'b-cutaway': () =>
    make('b', (i) => {
      const s = 5.5;
      const cells = [];
      for (let x = 0; x < 2; x++) for (let y = 0; y < 2; y++) for (let z = 0; z < 2; z++) if (!(x === 1 && y === 1 && z === 1)) cells.push([x, y, z]);
      cells.sort((a, b) => a[0] + a[1] + a[2] - (b[0] + b[1] + b[2]));
      for (const [x, y, z] of cells) i.box(-s + x * s, -s + y * s, z * s, s, s, s, z ? BRAND.indigo : shade(BRAND.indigo, 0.12), { noShadow: x + y + z > 0 });
      i.box(0.6, 0.6, s + 0.2, 2.6, 2.6, 2.6, BRAND.cyan, { noShadow: true });
      i.shadow(-s, -s, 2 * s, 2 * s);
    }),
  // C · Aperture: a window into the layer beneath the surface.
  'c-aperture': () =>
    make('c', (i) => {
      plate(i, 0, BRAND.cyan);
      const top = i.box(-7.5, -7.5, 3.4, 15, 15, 2.6, BRAND.indigo, { noShadow: true });
      top.top(`<circle cx="7.5" cy="7.5" r="3.6" fill="${shade(BRAND.indigo, 0.55)}"/><circle cx="8.1" cy="8.1" r="2.4" fill="${BRAND.cyan}"/>`);
    }),
  // D · T-shaft: a T whose stem descends through the layers.
  'd-tshaft': () =>
    make('d', (i) => {
      plate(i, 0, tint(BRAND.indigo, 0.4));
      i.box(-1.6, -1.6, 1.8, 3.2, 3.2, 9, BRAND.cyan, { noShadow: true });
      plate(i, 5, tint(BRAND.indigo, 0.2), { noShadow: true });
      i.box(-7.5, -2, 10.8, 15, 4, 2.6, BRAND.indigo, { noShadow: true });
    }),
  // E · Chevron depth: nested layers receding toward a light.
  'e-chevron': () =>
    make('e', (i) => {
      for (const [k, z] of [[0, 0], [1, 3], [2, 6]]) {
        const w = 15 - k * 4;
        i.box(-w / 2, -w / 2, z, w, w, 1.6, tint(BRAND.indigo, 0.3 - k * 0.15), { noShadow: k > 0 });
      }
      const [x, y] = P(0, 0, 7.6);
      i.raw(`<circle cx="${x}" cy="${y}" r="1.8" fill="${BRAND.cyan}" stroke="#fff" stroke-width=".6"/>`);
    }),
};

export function sheet(svgs) {
  const uri = (s) => `data:image/svg+xml;utf8,${encodeURIComponent(s)}`;
  const col = ([name, s]) =>
    `<div style="display:flex;flex-direction:column;align-items:center;gap:10px;padding:0 18px"><img src="${uri(s)}" width="128" height="128"><div style="display:flex;gap:12px;align-items:end"><img src="${uri(s)}" width="48" height="48"><img src="${uri(s)}" width="32" height="32"><img src="${uri(s)}" width="16" height="16"></div><div style="display:flex;align-items:center;gap:7px;font:650 17px -apple-system,Inter,sans-serif;letter-spacing:-.01em"><img src="${uri(s)}" width="26" height="26">TraceNaut</div><span style="font:11px Menlo;opacity:.6">${name}</span></div>`;
  const row = (bg, fg) => `<div style="display:flex;padding:22px 6px;background:${bg};color:${fg}">${Object.entries(svgs).map(col).join('')}</div>`;
  return `<body style="margin:0">${row('#111318', '#e4e7ee')}${row('#ffffff', '#1a1e27')}</body>`;
}

if (process.argv[2] === 'explore') {
  const dir = process.argv[3];
  mkdirSync(dir, { recursive: true });
  const svgs = Object.fromEntries(Object.entries(CANDIDATES).map(([k, f]) => [k, f()]));
  for (const [k, s] of Object.entries(svgs)) writeFileSync(`${dir}/${k}.svg`, s);
  writeFileSync(`${dir}/sheet.html`, sheet(svgs));
  console.log(`${Object.keys(svgs).length} candidates → ${dir}`);
}

// ------------------------------------------------------------------ the chosen mark
// "Cutaway": one solid with a single carved corner. The dark recess reveals the strata
// inside (the layers of a running system) and a lit core: see the surface, look inside,
// understand. Variants: full colour, monochrome for dark / light grounds, a dedicated 16 px.
const F = (n) => Number(n.toFixed(2));
const Q = (x, y, z, k, ox, oy) => {
  const [a, b] = P(x, y, z);
  return [F(ox + a * k), F(oy + b * k)];
};
const poly = (ptsList, fill, extra = '') => `<polygon points="${ptsList.map((p) => p.join(',')).join(' ')}" fill="${fill}"${extra}/>`;

export function markSvg(variant = 'color') {
  const small = variant === 'favicon';
  const size = small ? 16 : 64;
  // Fit the projected solid (S·cos30·2 wide, 2·S tall) inside the canvas with a margin.
  const S = 12;
  const margin = small ? 0.4 : 5;
  const k = (size - 2 * margin) / (2 * S);
  const ox = size / 2;
  const oy = margin + S * k - (small ? 0 : 1.2);
  const c = small ? 5.4 : 5.2; // where the carve starts (larger carve at 16 px)
  const mono = variant === 'mono-light' || variant === 'mono-dark';
  const pal = variant === 'mono-light'
    ? { top: ['#ffffff', '#e4e6f2'], left: ['#c9ccdc', '#aeb2c6'], right: ['#8d92a8', '#767b92'], floor: '#2a2d3a', wallL: '#3a3e50', wallR: '#30333f', core: ['#ffffff', '#d7dbe8'], glow: '#ffffff', edge: '#11131a' }
    : variant === 'mono-dark'
      ? { top: ['#5a5f74', '#3d4256'], left: ['#2f3346', '#23273a'], right: ['#1b1e2c', '#13151f'], floor: '#0b0c12', wallL: '#161823', wallR: '#10121a', core: ['#ffffff', '#e6e8f0'], glow: '#ffffff', edge: '#000000' }
      : { top: ['#a5a6ff', '#7778f2'], left: ['#6c6df0', '#5152cf'], right: ['#4243b4', '#2f2f8f'], floor: '#141238', wallL: '#2a2876', wallR: '#1f1d5c', core: ['#a5f3fc', '#22d3ee'], glow: '#22d3ee', edge: '#1e1b4b' };
  const id = `tn-${variant}`;
  const g = (name, [a, b], v = true) => `<linearGradient id="${id}-${name}" x1="0" y1="0" x2="${v ? 0 : 1}" y2="${v ? 1 : 0}"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
  const q = (x, y, z) => Q(x, y, z, k, ox, oy);
  const edge = small || mono ? '' : ` stroke="${pal.edge}" stroke-opacity=".35" stroke-width="${F(0.5)}" stroke-linejoin="round"`;
  // exterior (L-shaped top and side faces)
  const top = [q(0, 0, S), q(S, 0, S), q(S, c, S), q(c, c, S), q(c, S, S), q(0, S, S)];
  const left = [q(0, S, 0), q(S, S, 0), q(S, S, c), q(c, S, c), q(c, S, S), q(0, S, S)];
  const right = [q(S, 0, 0), q(S, S, 0), q(S, S, c), q(S, c, c), q(S, c, S), q(S, 0, S)];
  // recess: floor and the two inner walls
  const floor = [q(c, c, c), q(S, c, c), q(S, S, c), q(c, S, c)];
  const wallX = [q(c, c, c), q(c, S, c), q(c, S, S), q(c, c, S)]; // faces +x
  const wallY = [q(c, c, c), q(S, c, c), q(S, c, S), q(c, c, S)]; // faces +y
  // the lit core sitting on the recess floor, against the inner corner
  const r = small ? 3.6 : 3.4;
  const a0 = c + (small ? 0.5 : 0.7);
  const core = {
    top: [q(a0, a0, c + r), q(a0 + r, a0, c + r), q(a0 + r, a0 + r, c + r), q(a0, a0 + r, c + r)],
    left: [q(a0, a0 + r, c), q(a0 + r, a0 + r, c), q(a0 + r, a0 + r, c + r), q(a0, a0 + r, c + r)],
    right: [q(a0 + r, a0, c), q(a0 + r, a0 + r, c), q(a0 + r, a0 + r, c + r), q(a0 + r, a0, c + r)],
  };
  const [gx, gy] = q(a0 + r / 2, a0 + r / 2, c);
  const strata = small
    ? ''
    : [c + (S - c) * 0.38, c + (S - c) * 0.7]
        .map((z) => {
          const [ax, ay] = q(c, S, z);
          const [bx, by] = q(c, c, z);
          const [cx2, cy2] = q(S, c, z);
          return `<path d="M${ax} ${ay}L${bx} ${by}L${cx2} ${cy2}" fill="none" stroke="${mono ? '#ffffff' : '#8b8cf6'}" stroke-opacity="${mono ? 0.18 : 0.55}" stroke-width="${F(0.55)}"/>`;
        })
        .join('');
  const [sx, sy] = q(S / 2, S / 2, 0);
  const rim = small || mono ? '' : `<polyline points="${[q(0, S, S), q(0, 0, S), q(S, 0, S)].map((p) => p.join(',')).join(' ')}" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="${F(0.6)}" stroke-linejoin="round"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}"><defs>${g('t', pal.top)}${g('l', pal.left)}${g('r', pal.right)}${g('c', pal.core)}<radialGradient id="${id}-g"><stop offset="0" stop-color="${pal.glow}" stop-opacity="${mono ? 0.25 : 0.55}"/><stop offset="1" stop-color="${pal.glow}" stop-opacity="0"/></radialGradient><radialGradient id="${id}-s"><stop offset="0" stop-color="#05060d" stop-opacity=".32"/><stop offset="1" stop-color="#05060d" stop-opacity="0"/></radialGradient></defs>${small ? '' : `<ellipse cx="${sx}" cy="${F(sy + 2.2)}" rx="${F(size * 0.4)}" ry="${F(size * 0.11)}" fill="url(#${id}-s)"/>`}${poly(left, `url(#${id}-l)`, edge)}${poly(right, `url(#${id}-r)`, edge)}${poly(top, `url(#${id}-t)`, edge)}${poly(floor, pal.floor)}${poly(wallX, pal.wallR)}${poly(wallY, pal.wallL)}${strata}<ellipse cx="${gx}" cy="${gy}" rx="${F(r * k * 1.5)}" ry="${F(r * k * 0.8)}" fill="url(#${id}-g)"/>${poly(core.left, pal.core[1])}${poly(core.right, mono ? '#c4c8d6' : '#0e9fb8')}${poly(core.top, `url(#${id}-c)`)}${rim}</svg>`;
}

if (process.argv[2] === 'mark') {
  const dir = process.argv[3];
  mkdirSync(dir, { recursive: true });
  const svgs = { color: markSvg('color'), favicon: markSvg('favicon'), 'mono-light': markSvg('mono-light'), 'mono-dark': markSvg('mono-dark') };
  for (const [k, s] of Object.entries(svgs)) writeFileSync(`${dir}/mark-${k}.svg`, s);
  writeFileSync(`${dir}/mark.html`, sheet({ ...svgs, 'b-cutaway (before)': CANDIDATES['b-cutaway']() }));
  console.log('ok');
}
